mapper.select:
select *
from tb_cm_15
where 1 = 1
    and cm15_company = #{company}
    and cm15_factory = #{factory}

    and cm15_code LIKE CONCAT ('%',#{cm15Code},'%')


    and cm15_name LIKE CONCAT ('%',#{cm15Name},'%')


    and cm15_lock = #{cm15Lock}


    and cm15_exclusion = #{cm15Exclusion}

select *
from tb_cm_15
where 1 = 1
    and cm15_company = #{company}
    and cm15_factory = #{factory}
    and cm15_code = #{cm15Code}

select *
from tb_cm_15
where 1 = 1
    and cm15_company = #{company}
    and cm15_factory = #{factory}
    and cm15_code = #{cm15Code}
    and cm15_lock = 'N'

mapper.update:
update tb_cm_15
set
    cm15_name = #{cm15Name},
    cm15_lock = #{cm15Lock},
    cm15_exclusion = #{cm15Exclusion},
    cm15_rmk = #{cm15Rmk},
    cm15_updte = sysdate,
    cm15_empno = #{cm15Empno}
where 1 = 1
    and cm15_company = #{company}
    and cm15_factory = #{factory}
    and cm15_code = #{cm15Code}

mapper.delete:
